export const getPrepareNotarizationUrl = (statementId: string,
    params?: PrepareNotarizationParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/statements/${statementId}/notarization?${stringifiedParams}` : `/api/statements/${statementId}/notarization`
}

